// ============================================================
// n8n Code Node: BUILD EXTRACT PROMPT
// Prepares the OpenAI request body for structured extraction.
// Output field _requestBody is sent by the HTTP Request node.
// ============================================================

const input = $input.first().json;

const systemPrompt = `You are an intake classifier for Succeed, an education platform that connects students with enrichment programmes, summer schools, and academic experiences. The platform primarily serves high-school and early-university students.

Analyse the following inbound enquiry and extract structured data into the provided schema.

Rules:
- If a field cannot be determined from the message, use null and add the field name to missing_fields
- enquiry_category should reflect who is writing and what they want: providers offering programmes = provider_opportunity, schools looking for options = school_request, students asking about opportunities = student_request
- Fields like programme_topic, target_age_range, location, and format are bidirectional: for providers they describe the offering; for schools/students they describe the need or interest. Extract whichever applies.
- delivery_preference and timeline are requester-only fields — set to null for provider_opportunity
- fee_text is provider-only — set to null for school_request and student_request
- Mark enquiry_category as "spam" if the message is promotional, contains suspicious links, or is clearly unrelated to education
- For evidence, provide an array of {field, quote} objects. Each entry should name the extracted field and quote the supporting text directly from the message — do not paraphrase`;

let userContent = `Message: ${input.raw_message}`;
if (input.from_email) userContent += `\nSender email: ${input.from_email}`;
if (input.source) userContent += `\nSource: ${input.source}`;

const requestBody = {
  model: "gpt-5.4-mini",
  reasoning_effort: "low",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userContent },
  ],
  response_format: {
    type: "json_schema",
    json_schema: {
      name: "enquiry_extraction",
      strict: true,
      schema: {
        type: "object",
        properties: {
          enquiry_category: {
            type: "string",
            enum: ["provider_opportunity", "school_request", "student_request", "organisation_request", "spam", "unknown"]
          },
          sender_type: {
            type: "string",
            enum: ["programme_provider", "school", "student", "organisation", "unknown"]
          },
          sender_name: { type: ["string", "null"] },
          programme_name: { type: ["string", "null"] },
          programme_topic: { type: ["string", "null"] },
          target_age_range: { type: ["string", "null"] },
          location: { type: ["string", "null"] },
          format: {
            type: "string",
            enum: ["in_person", "online", "hybrid", "unknown"]
          },
          fee_text: { type: ["string", "null"] },
          delivery_preference: { type: ["string", "null"] },
          timeline: { type: ["string", "null"] },
          contact_email: { type: ["string", "null"] },
          intent: {
            type: "string",
            enum: ["partnership", "listing", "information_request", "support_request", "spam", "unclear"]
          },
          summary: { type: "string" },
          missing_fields: {
            type: "array",
            items: { type: "string" }
          },
          evidence: {
            type: "array",
            items: {
              type: "object",
              properties: {
                field: { type: "string" },
                quote: { type: "string" }
              },
              required: ["field", "quote"],
              additionalProperties: false
            }
          }
        },
        required: [
          "enquiry_category", "sender_type", "sender_name", "programme_name",
          "programme_topic", "target_age_range", "location", "format",
          "fee_text", "delivery_preference", "timeline", "contact_email",
          "intent", "summary", "missing_fields", "evidence"
        ],
        additionalProperties: false
      }
    }
  }
};

return [{
  json: {
    ...input,
    _requestBody: JSON.stringify(requestBody),
  }
}];

// ============================================================
// n8n Code Node: PROCESS EXTRACTION
// Parses the OpenAI response from the HTTP Request node.
// Merges extracted fields with original input data.
// ============================================================

// Original input data (from the Build Extract Prompt node)
const promptNode = $('Build Extract Prompt').first().json;
const { _requestBody, ...originalInput } = promptNode;

// API response (from the HTTP Request node)
const apiResponse = $input.first().json;

// Check for API errors
if (apiResponse.error) {
  return [{
    json: {
      ...originalInput,
      _extractionFailed: true,
      _failureReason: apiResponse.error.message || 'OpenAI API error',
    }
  }];
}

// Check for missing choices
if (!apiResponse.choices || !apiResponse.choices[0]) {
  return [{
    json: {
      ...originalInput,
      _extractionFailed: true,
      _failureReason: 'No choices in API response',
    }
  }];
}

const message = apiResponse.choices[0].message;

// Handle model refusals (safety filters)
if (message.refusal) {
  return [{
    json: {
      ...originalInput,
      _extractionFailed: true,
      _failureReason: message.refusal,
    }
  }];
}

// Parse the structured output
try {
  const extracted = JSON.parse(message.content);

  // Convert evidence from array of {field, quote} to object for downstream nodes
  if (Array.isArray(extracted.evidence)) {
    const evidenceObj = {};
    for (const entry of extracted.evidence) {
      evidenceObj[entry.field] = entry.quote;
    }
    extracted.evidence = evidenceObj;
  }

  return [{ json: { ...originalInput, ...extracted } }];
} catch (e) {
  return [{
    json: {
      ...originalInput,
      _extractionFailed: true,
      _failureReason: 'Failed to parse extraction response: ' + e.message,
    }
  }];
}

// ============================================================
// n8n Code Node: VALIDATE
// Deterministic checks: extraction failure gate, enum validation,
// spam detection, email validation, fee parsing, age normalization,
// confidence scoring, and processing status assignment.
// ============================================================

const input = { ...$input.first().json };

// --- 1. Extraction Failure Gate ---

if (input._extractionFailed) {
  return [{
    json: {
      ...input,
      enquiry_category: "unknown",
      sender_type: "unknown",
      sender_name: null,
      programme_name: null,
      programme_topic: null,
      target_age_range: null,
      location: null,
      format: "unknown",
      fee_text: null,
      fee_numeric: null,
      delivery_preference: null,
      timeline: null,
      contact_email: null,
      intent: "unclear",
      summary: "Extraction failed — raw message preserved for manual review",
      missing_fields: ["all"],
      evidence: {},
      processing_status: "extraction_failed",
      confidence_level: "low",
      validation_flags: ["extraction_failed"],
    }
  }];
}

// --- Initialize validation_flags ---

const validation_flags = [];

// --- 2. Enum Validation (defensive) ---

const ALLOWED = {
  enquiry_category: ["provider_opportunity", "school_request", "student_request", "organisation_request", "spam", "unknown"],
  sender_type: ["programme_provider", "school", "student", "organisation", "unknown"],
  format: ["in_person", "online", "hybrid", "unknown"],
  intent: ["partnership", "listing", "information_request", "support_request", "spam", "unclear"],
};

for (const [field, allowed] of Object.entries(ALLOWED)) {
  if (input[field] && !allowed.includes(input[field])) {
    validation_flags.push(`invalid_enum_${field}: "${input[field]}"`);
    input[field] = "unknown";
  }
}

// --- 3. Deterministic Spam Detection ---

const rawLower = (input.raw_message || "").toLowerCase();
let spam_signal_count = 0;

// Phrase patterns
const spamPhrases = [
  /grow your linkedin/i,
  /check out our tool/i,
  /seo services/i,
  /lead generation/i,
  /\bcrypto\b/i,
  /\bforex\b/i,
  /click here/i,
  /make money/i,
  /\$5000\/day/i,
  /\$\d{4,}\/day/i,
];

for (const pattern of spamPhrases) {
  if (pattern.test(input.raw_message || "")) {
    spam_signal_count++;
    validation_flags.push(`spam_phrase: ${pattern.source}`);
  }
}

// Suspicious TLDs
if (/\.(xyz|tk)\b/i.test(input.raw_message || "") || /\.(xyz|tk)\b/i.test(input.from_email || "")) {
  spam_signal_count++;
  validation_flags.push("spam_suspicious_tld");
}

// Link shorteners
if (/(bit\.ly|tinyurl)/i.test(input.raw_message || "")) {
  spam_signal_count++;
  validation_flags.push("spam_link_shortener");
}

// Apply spam signals
if (spam_signal_count >= 2) {
  input.enquiry_category = "spam";
  input.processing_status = "spam";
  validation_flags.push("spam_override_by_rules");
} else if (spam_signal_count === 1) {
  if (!input.processing_status || input.processing_status === "ok") {
    input.processing_status = "spam_suspected";
  }
  validation_flags.push("spam_suspected_single_signal");
}

// --- 4. Email Validation ---

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (input.contact_email && !emailRegex.test(input.contact_email)) {
  validation_flags.push("invalid_contact_email");
  input.contact_email = null;
  if (!input.missing_fields) input.missing_fields = [];
  if (!input.missing_fields.includes("contact_email")) {
    input.missing_fields.push("contact_email");
  }
}

// --- 5. Contact Email Fallback ---

if (!input.contact_email && input.from_email && emailRegex.test(input.from_email)) {
  input.contact_email = input.from_email;
  validation_flags.push("contact_email_fallback_from_metadata");
}

// --- 6. Fee Normalization ---

let fee_numeric = null;
if (input.fee_text) {
  const cleaned = input.fee_text.replace(/[^0-9.]/g, "");
  const parsed = parseFloat(cleaned);
  if (!isNaN(parsed)) {
    fee_numeric = parsed;
  }
}
input.fee_numeric = fee_numeric;

// --- 7. Age Range Normalization ---

if (input.target_age_range) {
  let age = input.target_age_range;
  // "16 to 18" -> "16-18"
  age = age.replace(/(\d+)\s*to\s*(\d+)/i, "$1-$2");
  // "ages 14-21" -> "14-21"
  age = age.replace(/ages?\s*/i, "");
  // Trim whitespace
  age = age.trim();
  input.target_age_range = age;
}

// --- 8. Confidence Level ---

const missingCount = (input.missing_fields || []).length;
const hasSpamOverride = spam_signal_count > 0;

let confidence_level;
if (missingCount <= 2 && !hasSpamOverride) {
  confidence_level = "high";
} else if (missingCount <= 4 && !hasSpamOverride) {
  confidence_level = "medium";
} else {
  confidence_level = "low";
}
input.confidence_level = confidence_level;

// --- 9. Processing Status ---

if (!input.processing_status) {
  input.processing_status = "ok";
}

// --- Output ---

input.validation_flags = validation_flags;

return [{ json: input }];

// ============================================================
// n8n Code Node: SCORE
// Deterministic category-aware scoring with 5 factors (100 pts).
// Each factor returns { score, evidence } for auditability.
// ============================================================

const input = { ...$input.first().json };

// --- Gate Checks ---

if (input.processing_status === "extraction_failed") {
  return [{
    json: {
      ...input,
      score: 0,
      tier: "failed",
      factor_scores: { fit_to_succeed: 0, value_and_actionability: 0, completeness: 0, contactability: 0, strategic_signal: 0 },
      factor_evidence: { fit_to_succeed: "Extraction failed", value_and_actionability: "N/A", completeness: "N/A", contactability: "N/A", strategic_signal: "N/A" },
    }
  }];
}

if (input.processing_status === "spam") {
  return [{
    json: {
      ...input,
      score: 0,
      tier: "spam",
      factor_scores: { fit_to_succeed: 0, value_and_actionability: 0, completeness: 0, contactability: 0, strategic_signal: 0 },
      factor_evidence: { fit_to_succeed: "Spam", value_and_actionability: "N/A", completeness: "N/A", contactability: "N/A", strategic_signal: "N/A" },
    }
  }];
}

if (input.processing_status === "spam_suspected") {
  return [{
    json: {
      ...input,
      score: 0,
      tier: "spam",
      factor_scores: { fit_to_succeed: 0, value_and_actionability: 0, completeness: 0, contactability: 0, strategic_signal: 0 },
      factor_evidence: { fit_to_succeed: "Spam suspected", value_and_actionability: "N/A", completeness: "N/A", contactability: "N/A", strategic_signal: "N/A" },
    }
  }];
}

// --- Factor 1: Fit to Succeed (25 pts) ---

function scoreFit(d) {
  const cat = d.enquiry_category;
  const sender = d.sender_type;
  const hasAge = !!d.target_age_range;
  const hasTopic = !!d.programme_topic;

  if (cat === "provider_opportunity") {
    if (sender === "programme_provider" && hasAge) {
      return { score: 25, evidence: `Programme provider targeting ${d.target_age_range} — direct Succeed audience fit` };
    }
    if (sender === "programme_provider") {
      return { score: 20, evidence: "Programme provider, age range not stated" };
    }
    if (sender === "organisation" && hasTopic) {
      return { score: 15, evidence: `Organisation with education-adjacent topic: ${d.programme_topic}` };
    }
    return { score: 10, evidence: "Organisation without clear education link" };
  }

  if (cat === "school_request") {
    if (sender === "school" && hasTopic) {
      return { score: 22, evidence: `School with relevant subject: ${d.programme_topic}` };
    }
    return { score: 18, evidence: "School without subject specificity" };
  }

  if (cat === "student_request") {
    if (hasTopic) {
      return { score: 18, evidence: `Student with specific interest: ${d.programme_topic}` };
    }
    return { score: 12, evidence: "Student without specific interest" };
  }

  // organisation_request, unknown
  return { score: 8, evidence: `Category: ${cat} — unclear audience fit` };
}

// --- Factor 2: Value and Actionability (25 pts) ---

function scoreValue(d) {
  const cat = d.enquiry_category;
  const intent = d.intent;
  const hasFee = !!d.fee_text || !!d.fee_numeric;
  const hasTopic = !!d.programme_topic;

  if (cat === "provider_opportunity") {
    if (intent === "partnership" && hasFee) {
      return { score: 25, evidence: `Partnership intent + fee: ${d.fee_text || d.fee_numeric} — strong commercial signal` };
    }
    if (intent === "partnership") {
      return { score: 18, evidence: "Partnership intent, no fee stated" };
    }
    if (intent === "listing" && hasFee) {
      return { score: 15, evidence: `Listing intent + fee: ${d.fee_text || d.fee_numeric}` };
    }
    if (intent === "listing") {
      return { score: 10, evidence: "Listing intent, no fee" };
    }
    return { score: 5, evidence: `Intent: ${intent} — unclear value` };
  }

  if (cat === "school_request" || cat === "student_request") {
    const hasNeed = d.summary && d.summary.length > 20;
    if (hasTopic && hasNeed) {
      return { score: 18, evidence: `Specific subject (${d.programme_topic}) + clear need stated` };
    }
    if (hasTopic) {
      return { score: 12, evidence: `Specific subject (${d.programme_topic}), vague need` };
    }
    return { score: 6, evidence: "No subject specificity" };
  }

  // organisation_request, unknown
  if (intent === "partnership") {
    return { score: 10, evidence: "Partnership intent stated, but organisation type" };
  }
  return { score: 3, evidence: `Intent: ${intent} — low actionability` };
}

// --- Factor 3: Completeness (20 pts) ---

function scoreCompleteness(d) {
  const cat = d.enquiry_category;

  let keyFields;
  if (cat === "provider_opportunity") {
    keyFields = ["sender_name", "programme_name", "programme_topic", "target_age_range", "location", "format", "fee_text", "contact_email"];
  } else if (cat === "school_request" || cat === "student_request") {
    keyFields = ["sender_name", "programme_topic", "target_age_range", "location", "delivery_preference", "timeline", "contact_email"];
  } else {
    keyFields = ["sender_name", "programme_name", "programme_topic", "target_age_range", "location", "format", "fee_text", "delivery_preference", "contact_email"];
  }

  const totalFields = keyFields.length;
  let populated = 0;
  for (const field of keyFields) {
    if (d[field] !== null && d[field] !== undefined && d[field] !== "" && d[field] !== "unknown") {
      populated++;
    }
  }

  let score;
  if (populated >= 6) score = 20;
  else if (populated >= 4) score = 14;
  else if (populated >= 2) score = 8;
  else score = 3;

  const label = cat === "provider_opportunity" ? "provider" : (cat === "school_request" || cat === "student_request") ? "requester" : "general";
  return {
    score,
    evidence: `${populated} of ${totalFields} ${label} key fields populated`,
  };
}

// --- Factor 4: Contactability (10 pts) ---

function scoreContactability(d) {
  if (d.contact_email) {
    const isFallback = (d.validation_flags || []).includes("contact_email_fallback_from_metadata");
    if (isFallback) {
      return { score: 6, evidence: `Email from metadata fallback: ${d.contact_email}` };
    }
    return { score: 10, evidence: `Direct contact email: ${d.contact_email}` };
  }
  return { score: 0, evidence: "No usable email" };
}

// --- Factor 5: Strategic Signal (20 pts, capped) ---

function scoreStrategic(d) {
  let total = 0;
  const signals = [];
  const raw = (d.raw_message || "").toLowerCase();

  // Fee >= 3000
  if (d.fee_numeric && d.fee_numeric >= 3000) {
    total += 5;
    signals.push(`Fee ${d.fee_text || d.fee_numeric} (+5)`);
  }

  // International location or language
  const internationalPattern = /\b(international|global|worldwide|countries)\b/i;
  const isInternational = internationalPattern.test(d.raw_message || "") ||
    (d.location && !["uk", "united kingdom", "england", "usa", "united states"].includes(d.location.toLowerCase()));
  if (isInternational) {
    total += 5;
    signals.push(d.location ? `International: ${d.location} (+5)` : "Global reach language (+5)");
  }

  // Specific cohort detail
  const hasSpecificCohort = (d.programme_name && d.programme_name !== "unknown") ||
    (d.target_age_range && d.target_age_range !== "unknown") ||
    (d.programme_topic && d.programme_topic !== "unknown");
  if (hasSpecificCohort) {
    total += 4;
    signals.push("Specific cohort detail (+4)");
  }

  // Well-known institution
  const prestigePattern = /\b(oxford|cambridge|imperial|harvard|mit|stanford|yale|princeton|columbia|lse|ucl|eth|caltech)\b/i;
  if (prestigePattern.test(d.raw_message || "") || prestigePattern.test(d.programme_name || "")) {
    total += 4;
    const match = (d.raw_message || "").match(prestigePattern) || (d.programme_name || "").match(prestigePattern);
    signals.push(`${match[0]} (+4)`);
  }

  // Selective / competitive language
  if (/\b(selective|competitive|limited places|limited spots)\b/i.test(d.raw_message || "")) {
    total += 3;
    signals.push("Selective/competitive (+3)");
  }

  // Multiple countries / "50+ countries"
  if (/\b(\d+\+?\s*countries|multiple countries)\b/i.test(d.raw_message || "")) {
    total += 3;
    signals.push("Multi-country reach (+3)");
  }

  // Cap at 20
  const capped = Math.min(total, 20);
  const evidence = signals.length > 0
    ? signals.join("; ") + (total > 20 ? ` = ${total}, capped at 20` : "")
    : "No strategic signals";

  return { score: capped, evidence };
}

// --- Calculate All Factors ---

const fit = scoreFit(input);
const value = scoreValue(input);
const completeness = scoreCompleteness(input);
const contactability = scoreContactability(input);
const strategic = scoreStrategic(input);

const totalScore = fit.score + value.score + completeness.score + contactability.score + strategic.score;

// --- Tier Assignment ---

let tier;
if (totalScore >= 75) tier = "high";
else if (totalScore >= 45) tier = "medium";
else if (totalScore >= 20) tier = "low";
else tier = "minimal";

// --- Output ---

return [{
  json: {
    ...input,
    score: totalScore,
    tier,
    factor_scores: {
      fit_to_succeed: fit.score,
      value_and_actionability: value.score,
      completeness: completeness.score,
      contactability: contactability.score,
      strategic_signal: strategic.score,
    },
    factor_evidence: {
      fit_to_succeed: fit.evidence,
      value_and_actionability: value.evidence,
      completeness: completeness.evidence,
      contactability: contactability.evidence,
      strategic_signal: strategic.evidence,
    },
  }
}];

// ============================================================
// n8n Code Node: ROUTE
// Deterministic action assignment via rule matrix, overrides,
// needs_review flags, and reply question generation.
// ============================================================

const input = { ...$input.first().json };

// --- Reply Questions Mapping (category-aware) ---

const PROVIDER_QUESTIONS = {
  fee_text: "Could you share your programme's fee structure?",
  target_age_range: "What age range is your programme designed for?",
  programme_name: "What is the name of your programme?",
  programme_topic: "What subject area does your programme focus on?",
  location: "Where is your programme based?",
  format: "Is your programme in-person, online, or hybrid?",
};

const REQUESTER_QUESTIONS = {
  target_age_range: "What age range are your students?",
  programme_topic: "What subject areas are you most interested in?",
  location: "Where are you based?",
  delivery_preference: "Do you have a preference for in-person, online, or overseas programmes?",
  timeline: "When are you looking for programmes — this summer, next term, or another timeframe?",
};

// Fields excluded from reply_questions (internal/system)
const EXCLUDED_FIELDS = ["sender_name", "contact_email", "from_email", "evidence", "summary", "missing_fields"];

function generateReplyQuestions(d) {
  const questions = [];
  const missingFields = d.missing_fields || [];
  const cat = d.enquiry_category;

  const questionMap = cat === "provider_opportunity" ? PROVIDER_QUESTIONS : REQUESTER_QUESTIONS;

  for (const field of missingFields) {
    if (EXCLUDED_FIELDS.includes(field)) continue;
    if (questionMap[field]) {
      questions.push(questionMap[field]);
    }
  }

  // Generic email question if contact is missing
  if (!d.contact_email && !missingFields.includes("contact_email")) {
    // contact_email is missing but not in missing_fields — add generic
  }
  if (missingFields.includes("contact_email") || (!d.contact_email && !d.from_email)) {
    questions.push("What is the best email to reach you?");
  }

  return questions;
}

// --- Routing Rule Matrix (first match wins) ---

const cat = input.enquiry_category;
const tier = input.tier;
const status = input.processing_status;
const hasContactEmail = !!input.contact_email;
const hasFromEmail = !!input.from_email;
const hasAnyContact = hasContactEmail || hasFromEmail;

let action = "manual_review";
let action_note = null;
let needs_review = false;

// Rule 1: Extraction failed
if (status === "extraction_failed") {
  action = "manual_review";
  needs_review = true;
}
// Rule 2: Hard spam
else if (status === "spam") {
  action = "archive";
}
// Rule 3: Suspected spam
else if (status === "spam_suspected") {
  action = "manual_review";
  needs_review = true;
}
// Rule 4: Provider, high/medium tier, has contact email
else if (cat === "provider_opportunity" && (tier === "high" || tier === "medium") && hasContactEmail) {
  action = "schedule_call";
}
// Rule 5: Provider, high/medium tier, no contact email
else if (cat === "provider_opportunity" && (tier === "high" || tier === "medium") && !hasContactEmail) {
  action = "request_info";
}
// Rule 6: Provider, low/minimal tier
else if (cat === "provider_opportunity" && (tier === "low" || tier === "minimal")) {
  action = "request_info";
}
// Rule 7: School/student, high/medium tier, has contact email
else if ((cat === "school_request" || cat === "student_request") && (tier === "high" || tier === "medium") && hasContactEmail) {
  action = "share_options";
}
// Rule 8: School/student, high/medium tier, no contact email
else if ((cat === "school_request" || cat === "student_request") && (tier === "high" || tier === "medium") && !hasContactEmail) {
  action = "manual_review";
}
// Rule 9: School/student, low tier, has contact email
else if ((cat === "school_request" || cat === "student_request") && tier === "low" && hasContactEmail) {
  action = "request_info";
}
// Rule 10: School/student, low/minimal tier, no contact email
else if ((cat === "school_request" || cat === "student_request") && (tier === "low" || tier === "minimal") && !hasContactEmail) {
  action = "manual_review";
}
// Rule 11: Organisation/unknown
else if (cat === "organisation_request" || cat === "unknown") {
  action = "manual_review";
}

// --- Overrides ---

// Override 1: No-contact — downgrade outbound actions if no contact channel at all
if (!hasAnyContact && ["schedule_call", "request_info", "share_options"].includes(action)) {
  action_note = `Downgraded to manual_review: no contact channel available`;
  action = "manual_review";
  needs_review = true;
}

// Override 2: Contact-email — downgrade schedule_call if only from_email (no direct contact_email)
if (action === "schedule_call" && !hasContactEmail && hasFromEmail) {
  action_note = "Downgraded from schedule_call: no direct contact email";
  action = "request_info";
}

// Override 3: Low-confidence review flag (skip for spam/archive — those are already handled)
if (input.confidence_level === "low" && action !== "archive") {
  needs_review = true;
}

// Override 5: Extraction failure review flag
if (status === "extraction_failed") {
  needs_review = true;
}

// --- Generate Reply Questions ---

const reply_questions = generateReplyQuestions(input);

// --- Output ---

return [{
  json: {
    ...input,
    action,
    action_note,
    needs_review,
    reply_questions,
  }
}];

// ============================================================
// n8n Code Node: BUILD REPLY PROMPT
// Prepares the OpenAI request body for draft email generation.
// Output field _requestBody is sent by the HTTP Request node.
// ============================================================

const input = $input.first().json;

const senderName = input.sender_name || "Unknown sender";
const programmeName = input.programme_name || "Not specified";
const programmeTopic = input.programme_topic || "Not specified";
const questionsText = (input.reply_questions && input.reply_questions.length > 0)
  ? input.reply_questions.join("; ")
  : "None";

const systemPrompt = `You are writing a follow-up email on behalf of Succeed, an education platform that connects high-school and early-university students with enrichment programmes and academic experiences.

Enquiry context:
- Sender: ${senderName}
- Type: ${input.sender_type}
- Category: ${input.enquiry_category}
- Programme: ${programmeName}
- Topic: ${programmeTopic}
- Summary: ${input.summary}
- Priority: ${input.tier} (score: ${input.score}/100)
- Action: ${input.action}
- Questions to ask: ${questionsText}

Rules by action:
- schedule_call: Be warm and specific. Reference their programme by name. Propose a 15-minute introductory call this week. Mention Succeed's student audience.
- request_info: Acknowledge their interest. Ask the specific questions listed in "Questions to ask" above, rephrased naturally into your email. Do NOT use internal field names. Keep it inviting, not transactional.
- share_options: Acknowledge their need. Briefly explain how Succeed can help. Invite them to explore relevant options or suggest a next step.
- manual_review: Write a polite acknowledgement. Let them know their enquiry has been received and the team will follow up shortly. Keep it brief and warm.
- archive: Write a brief, polite response thanking them for reaching out. Keep it generic and professional.

Constraints:
- Under 80 words for schedule_call and share_options; under 120 words for request_info (needs room for multiple questions)
- For request_info: ask only the top 3 most important questions from the list. If more are needed, note "we may follow up with a few more questions" rather than cramming them all in.
- Professional but approachable tone
- Sign off as "The Succeed Team"
- No exclamation marks. No "excited to hear from you." No filler.
- Reference specific details from the enquiry to show this is not a template.`;

const requestBody = {
  model: "gpt-5.4-mini",
  reasoning_effort: "low",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: `Write a ${input.action} follow-up email for this enquiry.` },
  ],
  max_completion_tokens: 300,
};

return [{
  json: {
    ...input,
    _requestBody: JSON.stringify(requestBody),
  }
}];

